`new Promise(executor)` 的构造函数会**同步**调用 executor，并把 resolve 和 reject 作为参数传进去。这意味着 executor 里的代码在 new 的那一刻就开始跑了——如果 executor 里有同步的 resolve，Promise 在构造结束时就已经 fulfilled 了；如果 resolve 被包在 setTimeout 里，Promise 在构造结束时还是 pending。

这个设计的工程意义是：调用方通过控制 resolve/reject 的调用时机来决定 Promise 何时定型（settle），而不需要知道内部实现。构造函数必须用 try/catch 包住 executor 的调用——如果 executor 抛异常，应该直接让 Promise rejected，而不是让异常逃逸到 new 语句外。这是所有实现的第一道防线：
```javascript
try {
    executor(this.resolve.bind(this), this.reject.bind(this));
} catch (e) {
    this.reject(e);
}
```

还有一个常被忽略的细节：resolve 和 reject 必须绑定 this，否则作为参数传递时 this 会丢失。bind 或箭头函数都可以，但 bind 是最稳妥的方式。

const PENDING = 'pending';
const FULFILLED = 'fulfilled';
const REJECTED = 'rejected';

class MyPromise {
    constructor(executor) {
        this.status = PENDING;
        this.value = undefined;       // fulfilled 时存 value，rejected 时存 reason
        this.onFulfilledCallbacks = []; // pending 时暂存的成功回调
        this.onRejectedCallbacks = [];  // pending 时暂存的失败回调

        const resolve = (value) => {
            if (this.status !== PENDING) return; // 状态锁定：只迁移一次

            // resolve 的值如果是 Promise/thenable，递归解析
            if (value instanceof MyPromise || (value !== null && typeof value === 'object' && typeof value.then === 'function')) {
                value.then(resolve, reject); // 吸收 thenable
                return;
            }

            this.status = FULFILLED;
            this.value = value;
            this.onFulfilledCallbacks.forEach(fn => fn());
        };

        const reject = (reason) => {
            if (this.status !== PENDING) return;
            this.status = REJECTED;
            this.value = reason;
            this.onRejectedCallbacks.forEach(fn => fn());
        };

        try {
            executor(resolve, reject); // 同步调用 executor
        } catch (e) {
            reject(e); // executor 抛异常 → rejected
        }
    }

    then(onFulfilled, onRejected) {
        // 值穿透：onFulfilled/onRejected 不是函数时透传值
        onFulfilled = typeof onFulfilled === 'function' ? onFulfilled : value => value;
        onRejected = typeof onRejected === 'function' ? onRejected : reason => { throw reason; };

        const promise2 = new MyPromise((resolve, reject) => {
            const handle = (callback) => {
                queueMicrotask(() => { // 微任务异步执行
                    try {
                        const x = callback(this.value);
                        resolvePromise(promise2, x, resolve, reject); // 核心：递归解析
                    } catch (e) {
                        reject(e);
                    }
                });
            };

            if (this.status === FULFILLED) {
                handle(onFulfilled);
            } else if (this.status === REJECTED) {
                handle(onRejected);
            } else { // pending：存队列，发布订阅
                this.onFulfilledCallbacks.push(() => handle(onFulfilled));
                this.onRejectedCallbacks.push(() => handle(onRejected));
            }
        });
        return promise2; // 返回新 Promise，链式调用的基础
    }

    catch(onRejected) {
        return this.then(null, onRejected);
    }

    finally(callback) {
        return this.then(
            value => MyPromise.resolve(callback()).then(() => value),
            reason => MyPromise.resolve(callback()).then(() => { throw reason; })
        );
    }

    // 静态方法
    static resolve(value) {
        if (value instanceof MyPromise) return value;
        return new MyPromise(resolve => resolve(value));
    }

    static reject(reason) {
        return new MyPromise((_, reject) => reject(reason));
    }

    static all(promises) {
        return new MyPromise((resolve, reject) => {
            const results = [];
            let count = 0;
            const items = Array.from(promises);
            if (items.length === 0) return resolve(results); // 空数组立即 resolve
            items.forEach((p, i) => {
                MyPromise.resolve(p).then( // 非 Promise 值自动包装
                    value => {
                        results[i] = value;
                        if (++count === items.length) resolve(results);
                    },
                    reason => reject(reason) // 任一失败立即 reject（短路）
                );
            });
        });
    }

    static race(promises) {
        return new MyPromise((resolve, reject) => {
            Array.from(promises).forEach(p => {
                MyPromise.resolve(p).then(resolve, reject); // 第一个定型的决定结果
            });
        });
    }
}

// Promise Resolution Procedure（Promises/A+ 2.3 节）
function resolvePromise(promise2, x, resolve, reject) {
    // 循环引用检测：x === promise2 则 reject TypeError
    if (x === promise2) {
        return reject(new TypeError('Chaining cycle detected'));
    }

    // x 是 MyPromise 实例：等它 settle 后透传
    if (x instanceof MyPromise) {
        x.then(resolve, reject);
        return;
    }

    // x 是 thenable：duck type 检测 .then 方法
    if (x !== null && (typeof x === 'object' || typeof x === 'function')) {
        let called = false; // 防止 thenable 的 then 被多次调用
        try {
            const then = x.then; // getter 可能抛异常
            if (typeof then === 'function') {
                then.call(
                    x,
                    y => { // resolvePromise
                        if (called) return;
                        called = true;
                        resolvePromise(promise2, y, resolve, reject); // 递归解析
                    },
                    r => { // rejectPromise
                        if (called) return;
                        called = true;
                        reject(r);
                    }
                );
            } else {
                resolve(x); // 有 .then 但不是函数，当普通值处理
            }
        } catch (e) {
            if (called) return; // 已经调用过则忽略后续异常
            called = true;
            reject(e);
        }
    } else {
        resolve(x); // 普通值直接 resolve
    }
}

// 验证：接入 promises-aplus-tests 套件
MyPromise.deferred = function () {
    let result = {};
    result.promise = new MyPromise((resolve, reject) => {
        result.resolve = resolve;
        result.reject = reject;
    });
    return result;
};
module.exports = MyPromise;
